'use strict';
const {test}=require('node:test');const assert=require('node:assert/strict');
const G=require('./garage');
const v=(id='a')=>({id,name:' Ma voiture ',fuel:'Gazole',consumption:5.5,tankCapacity:50,illustration:'citadine_bleue',fillPercent:80});
const one=()=>G.addVehicle(G.emptyGarage(),v());
test('empty garage',()=>assert.deepEqual(G.emptyGarage(),{schemaVersion:1,revision:0,defaultVehicleId:null,vehicles:[]}));
test('add vehicle, trim name, default and revision',()=>{let g=one();assert.equal(g.vehicles[0].name,'Ma voiture');assert.equal(g.defaultVehicleId,'a');assert.equal(g.revision,1)});
test('add second vehicle keeps default',()=>{let g=G.addVehicle(one(),v('b'));assert.equal(g.defaultVehicleId,'a');assert.equal(g.vehicles.length,2)});
test('cannot add duplicate',()=>assert.throws(()=>G.addVehicle(one(),v()),/duplicate/));
test('edit preserves id and other fields',()=>{let g=G.editVehicle(one(),'a',{consumption:6,fillPercent:35});assert.equal(g.vehicles[0].fuel,'Gazole');assert.equal(g.vehicles[0].fillPercent,35);assert.equal(g.revision,2)});
test('edit cannot change id',()=>assert.throws(()=>G.editVehicle(one(),'a',{id:'b'}),/unsupported/));
test('edit unknown fails',()=>assert.throws(()=>G.editVehicle(one(),'missing',{name:'X'}),/not found/));
test('remove default chooses remaining',()=>{let g=G.removeVehicle(G.addVehicle(one(),v('b')),'a');assert.equal(g.defaultVehicleId,'b')});
test('remove last resets default',()=>{let g=G.removeVehicle(one(),'a');assert.equal(g.defaultVehicleId,null);assert.equal(g.vehicles.length,0)});
test('remove unknown fails',()=>assert.throws(()=>G.removeVehicle(one(),'z'),/not found/));
test('set default',()=>{let g=G.setDefaultVehicle(G.addVehicle(one(),v('b')),'b');assert.equal(G.getDefaultVehicle(g).id,'b')});
test('set default unknown fails',()=>assert.throws(()=>G.setDefaultVehicle(one(),'b'),/not found/));
test('empty default is null',()=>assert.equal(G.getDefaultVehicle(G.emptyGarage()),null));
test('immutable operations',()=>{let g=one(),h=G.editVehicle(g,'a',{name:'Other'});assert.equal(g.vehicles[0].name,'Ma voiture');assert.notEqual(g,h)});
test('all six fuels valid',()=>G.FUELS.forEach(f=>assert.equal(G.validateVehicle({...v(),fuel:f}).fuel,f)));
test('all 16 illustrations valid',()=>G.ICONS.forEach(i=>assert.equal(G.validateVehicle({...v(),illustration:i}).illustration,i)));
test('reject unknown fuel',()=>assert.throws(()=>G.validateVehicle({...v(),fuel:'GPL'}),/fuel/));
test('reject unknown illustration',()=>assert.throws(()=>G.validateVehicle({...v(),illustration:'waze'}),/illustration/));
test('reject invalid percentages',()=>[0,101,2.5,NaN].forEach(fillPercent=>assert.throws(()=>G.validateVehicle({...v(),fillPercent}),/percentage/)));
test('reject invalid capacities',()=>[0,-1,NaN,Infinity,2001].forEach(tankCapacity=>assert.throws(()=>G.validateVehicle({...v(),tankCapacity}),/capacity/)));
test('reject invalid consumption',()=>[0,-2,NaN,Infinity,101].forEach(consumption=>assert.throws(()=>G.validateVehicle({...v(),consumption}),/consumption/)));
test('reject bad name and id',()=>{assert.throws(()=>G.validateVehicle({...v(),name:'   '}),/name/);assert.throws(()=>G.validateVehicle({...v(),id:'bad id'}),/id/)});
test('reject duplicate IDs on validation',()=>assert.throws(()=>G.validateGarage({revision:1,defaultVehicleId:'a',vehicles:[v(),v()]}),/duplicate/));
test('reject missing default on validation',()=>assert.throws(()=>G.validateGarage({revision:1,defaultVehicleId:'z',vehicles:[v()]}),/default/));
test('reject invalid revision',()=>assert.throws(()=>G.validateGarage({...one(),revision:-1}),/revision/));
test('reject more than 30 vehicles',()=>assert.throws(()=>G.validateGarage({revision:1,defaultVehicleId:'a',vehicles:Array.from({length:31},(_,i)=>v('v'+i))}),/garage/));
test('legacy migration imports capacity and consumption',()=>{let g=G.migrateLegacy(G.emptyGarage(),{tankSize:'55',consumption:'6.2',fuel:'E10'},'legacy_1');assert.equal(g.vehicles[0].tankCapacity,55);assert.equal(g.vehicles[0].fuel,'E10')});
test('legacy migration skips incomplete values',()=>assert.deepEqual(G.migrateLegacy(G.emptyGarage(),{tankSize:55},'legacy'),G.emptyGarage()));
test('legacy migration is idempotent',()=>{let g=one();assert.deepEqual(G.migrateLegacy(g,{tankSize:55,consumption:6},'legacy'),g)});
test('legacy invalid fuel defaults safely',()=>assert.equal(G.migrateLegacy(G.emptyGarage(),{tankSize:55,consumption:6,fuel:'???'},'legacy').vehicles[0].fuel,'Gazole'));
test('legacy missing id fails if eligible',()=>assert.throws(()=>G.migrateLegacy(G.emptyGarage(),{tankSize:55,consumption:6},''),/id/));
test('prepare save when revision exactly one ahead',()=>{let x=G.prepareSave(one(),G.emptyGarage(),0);assert.equal(x.status,'ready');assert.equal(x.expectedRevision,0)});
test('prepare save rejects concurrent server changes',()=>assert.equal(G.prepareSave(one(),one(),0).status,'conflict'));
test('prepare save rejects no local changes',()=>assert.equal(G.prepareSave(G.emptyGarage(),G.emptyGarage(),0).status,'conflict'));
test('prepare save allows multiple offline edits as one write',()=>{let x=G.prepareSave(G.editVehicle(one(),'a',{name:'x'}),G.emptyGarage(),0);assert.equal(x.status,'ready');assert.equal(x.next.revision,1);assert.equal(x.next.vehicles[0].name,'x')});
test('prepare save rejects missing base revision',()=>assert.throws(()=>G.prepareSave(one(),G.emptyGarage()),/base revision/));
test('validations do not mutate input',()=>{let x=v();G.validateVehicle(x);assert.equal(x.name,' Ma voiture ')});
